#!/bin/bash
set -e
MONITOR_DIR="/opt/siempria-monitor"
BACKUP_DIR="$MONITOR_DIR/backups/$(date +%Y%m%d_%H%M%S)"
TMPDIR="$(mktemp -d)"

echo "=== FIX Roles v2: group_access OR organization_access ==="

echo "[1/4] Extrayendo..."
echo "" | base64 -d | tar xzf - -C "$TMPDIR"

echo "[2/4] Backup..."
mkdir -p "$BACKUP_DIR"
cp "$MONITOR_DIR/backend/services/multitenancy_service.py" "$BACKUP_DIR/" 2>/dev/null || true
cp "$MONITOR_DIR/backend/routes/devices.py" "$BACKUP_DIR/" 2>/dev/null || true
cp "$MONITOR_DIR/backend/routes/dahua.py" "$BACKUP_DIR/" 2>/dev/null || true
cp "$MONITOR_DIR/backend/routes/organizations.py" "$BACKUP_DIR/" 2>/dev/null || true

echo "[3/4] Aplicando fix..."
cp "$TMPDIR/multitenancy_service.py" "$MONITOR_DIR/backend/services/multitenancy_service.py"
cp "$TMPDIR/devices.py" "$MONITOR_DIR/backend/routes/devices.py"
cp "$TMPDIR/dahua.py" "$MONITOR_DIR/backend/routes/dahua.py"
cp "$TMPDIR/organizations.py" "$MONITOR_DIR/backend/routes/organizations.py"

rm -rf "$TMPDIR"

echo "[4/4] Reiniciando..."
sudo systemctl restart siempria-backend
sleep 3

if sudo systemctl is-active --quiet siempria-backend; then
    echo ""
    echo "=== FIX v2 APLICADO ==="
    echo "Cambio: group_access='all' OR organization_access='all'"
    echo "Import directo de roles_collection (sin try/except)"
    echo ""
    echo "Verificar: login como aray y ver Dispositivos"
else
    echo "[!] Error - ver: sudo journalctl -u siempria-backend -n 20"
fi
